import { list_all_cargo_spaces } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import EditContainerDialog from "./PopUpsDialogues/EditContainerDialog.vue";
import DeleteContainerDialog from "./PopUpsDialogues/DeleteContainerDialog.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    EditContainerDialog,
    DeleteContainerDialog
  },
  data() {
    return {
      componentCheck: 0,
      search: "",
      fixed: true,
      searchlist: "",
      tableLoading: false,
      conatainerHeaders: [{
        text: "Name",
        value: "cargo_space_name",
        sortable: false
      }, {
        text: "Type",
        value: "cargo_space_type",
        sortable: false
      },
      // { text: "Capacity", value: "no_of_employees_in_team", sortable: false },
      {
        text: "Length(mts)",
        value: "inner_length_in_mts",
        sortable: false
      }, {
        text: "Width(mts)",
        value: "inner_width_in_mts",
        sortable: false
      }, {
        text: "Height(mts)",
        value: "inner_height_in_mts",
        sortable: false
      }, {
        text: "Weight(lb)",
        value: "max_load_in_lb",
        sortable: false
      }, {
        text: "Action",
        value: "actions",
        sortable: false
      }],
      SnackBarComponent: {},
      tableData: [],
      editContainerDialog: false,
      rowInfo: {},
      deleteContainerDialog: false
    };
  },
  async mounted() {
    await this.fetch_cargo_conatiners();
  },
  methods: {
    edit_item(item) {
      this.componentCheck = 1;
      this.editContainerDialog = true;
      this.rowInfo = item;
    },
    delete_item(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.deleteContainerDialog = true;
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.deleteContainerDialog = false;
      this.editContainerDialog = false;
      await this.fetch_cargo_conatiners();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_cargo_conatiners() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_all_cargo_spaces, {
          input: {}
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_all_cargo_spaces);
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
